mapper.sql:
WHERE r.owner_dept_id IS NOT NULL AND r.created_by IS NOT NULL AND r.config_hash IS NOT NULL AND r.environment=#{environment}
AND 1=0
    AND r.owner_dept_id IN #{id}

AND r.owner_dept_id=#{query.ownerDeptId}
AND r.status=#{query.status}
AND r.vehicle_type_code=#{query.vehicleTypeCode}
AND r.inspection_type_code=#{query.inspectionTypeCode}

mapper.select:

JOIN vi_station s ON s.id=#{stationId} AND s.enabled=1
JOIN sys_dept station_dept ON station_dept.dept_id=s.dept_id AND station_dept.status='0' AND station_dept.del_flag='0'
WHERE r.status='PUBLISHED' AND r.environment=#{environment}
AND r.config_hash IS NOT NULL AND r.approved_hash IS NOT NULL AND r.published_at IS NOT NULL
AND d.status='0' AND d.del_flag='0' AND (r.owner_dept_id=station_dept.dept_id OR FIND_IN_SET(r.owner_dept_id,station_dept.ancestors)>0)
AND r.vehicle_type_code=#{vehicle} AND r.inspection_type_code=#{inspection}
AND r.effective_from <= #{at,typeHandler=com.xinyi.rongli.platform.mybatis.ViUtcInstantTypeHandler}
AND (r.effective_to IS NULL OR r.effective_to > #{at,typeHandler=com.xinyi.rongli.platform.mybatis.ViUtcInstantTypeHandler})
ORDER BY r.id

SELECT COUNT(*) FROM vi_price_rule r JOIN sys_dept existing_company ON existing_company.dept_id=r.owner_dept_id
JOIN sys_dept candidate_company ON candidate_company.dept_id=#{row.ownerDeptId}
WHERE r.id != #{row.id} AND r.status='PUBLISHED' AND r.environment=#{row.environment}
AND r.vehicle_type_code=#{row.vehicleTypeCode} AND r.inspection_type_code=#{row.inspectionTypeCode}
AND (r.owner_dept_id=candidate_company.dept_id OR FIND_IN_SET(r.owner_dept_id,candidate_company.ancestors)>0
    OR FIND_IN_SET(candidate_company.dept_id,existing_company.ancestors)>0)
AND r.id != #{replacesId}
AND (#{row.effectiveTo,jdbcType=TIMESTAMP,typeHandler=com.xinyi.rongli.platform.mybatis.ViUtcInstantTypeHandler} IS NULL
    OR r.effective_from < #{row.effectiveTo,jdbcType=TIMESTAMP,typeHandler=com.xinyi.rongli.platform.mybatis.ViUtcInstantTypeHandler})
AND (r.effective_to IS NULL OR r.effective_to > #{row.effectiveFrom,typeHandler=com.xinyi.rongli.platform.mybatis.ViUtcInstantTypeHandler})
